def valid_binary_strings_with_cost(n,k):
    answer=[]
    def visit(i,cost,path):
        if i==n:answer.append(path);return
        visit(i+1,cost,path+'0')
        if (not path or path[-1]=='0') and cost+i<=k:visit(i+1,cost+i,path+'1')
    visit(0,0,'');return answer

